/**
 * ARCA's `Cuit_pais_cliente` catalogue as rows, transcribed verbatim from PRODUCTION
 * `FEXGetPARAM_DST_CUIT` on 2026-09-04, with an ISO country and an entity type derived from each
 * description. Re-take with:
 *
 *   PROBE_ENVIRONMENT=production pnpm dump:wsfex-table cuit
 *
 * `DST_CUIT` and `DST_Ds` are the authority's own two columns, kept under the authority's own names so a
 * row can be diffed against a fresh dump without a rename in between. `countryIso` and `entityType` are
 * *ours*, derived from `DST_Ds` and carrying no authority behind them — never send either to ARCA, and
 * never validate against them. `DST_CUIT` is the whole of what `toCountryTaxId` checks against — this
 * file is the single transcription, and `destination-codes.ts` derives its membership set from it. The
 * other two columns are for presentation, a country picker, and reconciliation.
 *
 * The table is a country x entity-type grid: 306 distinct descriptions, normally three rows each.
 *
 * **`entityType`** is exact. It is the description's own suffix, which every row carries:
 * `Persona Física` -> `INDIVIDUAL`, `Persona Jurídica` -> `LEGAL_ENTITY`, `Otro tipo de Entidad` ->
 * `OTHER_ENTITY`. No rows fail to parse. Note ARCA mislabels its own two catch-alls:
 * `PARA PERSONAS FISICAS DE ...` rows carry the `Persona Jurídica` suffix, and the suffix is what is
 * transcribed here — the name is not evidence.
 *
 * **`countryIso`** is a judgement, not a transcription. ARCA publishes no ISO annotation and no país code
 * on these rows, so every value here was assigned by hand against the description. The rule:
 *
 * - The territory's own ISO 3166-1 alpha-2 code where it has one — including the many dependencies that do
 *   (`Guadalupe` `GP`, `Curazao` `CW`, `Islas Feroe` `FO`, `Isla de Man` `IM`).
 * - Otherwise the smallest coded territory that wholly contains it: `MADEIRA` and `ISLAS AZORES` -> `PT`,
 *   `Islas Canarias` -> `ES`, `LABUAN` -> `MY`, `Hawai` -> `US`, `TRIESTE` and `CAMPIONE D@ITALIA` ->
 *   `IT`, `ZONA LIBRE DE OSTRAVA` -> `CZ`, `ISLA QESHM` -> `IR`, the six Guernsey dependencies -> `GG`.
 *   This is lossy on purpose and is the reason `countryIso` must not drive a fiscal decision: Madeira is a
 *   distinct tax jurisdiction from mainland Portugal, which is precisely why ARCA lists it separately.
 * - `null` where the label names no single territory. That is 84 rows across 28 descriptions:
 *   the `POS.<nationality> (<continent>)` possession buckets, the `INDETERMINADO (<continent>)` catch-alls,
 *   the two `PARA PERSONAS FISICAS DE ...` descriptions, the combined `ISLAS DEL CANAL:...` row (it spans `GG` and
 *   `JE`), `ISLAS PACIFICO`, `REGIMEN APLICABLE A LAS SA FINANCIERAS` (a legal regime, not a place),
 *   `YUGOSLAVIA` and `ANTILLAS HOLANDESAS` (both dissolved into several successors).
 *
 * `Islas Georgias del Sur` and `Islas Sandwinch del Sur` carry `GS`, which is the alpha-2 ISO assigns to
 * them. That is a transport code for interoperating with systems that speak ISO, chosen the same way every
 * other code in this column was, and it is not this service's view of who the islands belong to. The
 * Argentine position — that they are Argentine, along with the Malvinas — is recorded in
 * `destination-codes.ts` next to `DESTINATION_ISLAS_MALVINAS`, which is where a reader looking for it will
 * be. Keep the two separate: this column exists to be handed to a counterparty's software, and overloading
 * it to carry a claim would break the interop it is for while stating the claim somewhere nobody reads.
 *
 * 247 distinct ISO codes are used, and one code can appear under several descriptions — `CD` is
 * `ZAIRE`, `Congo, República Democrática del` and `Congo, República Democrática del  (Ex Zaire)`; `FM` is
 * three spellings of Micronesia; `PS` is `GAZA` and `TERRITORIOS AUTONOMOS PALESTINOS`. Do not key
 * anything by `countryIso` expecting it to be unique.
 *
 * 917 rows.
 */

/** Whether the row's CUIT identifies a natural person, a company, or neither. ARCA's own three-way split. */
export type CountryTaxIdEntityType = 'INDIVIDUAL' | 'LEGAL_ENTITY' | 'OTHER_ENTITY';

export interface CountryTaxIdRow {
    /** The authority's `Cuit_pais_cliente`, 11 digits, verbatim. */
    readonly DST_CUIT: string;
    /** The authority's description, verbatim — `"<destination> - <entity type>"`. */
    readonly DST_Ds: string;
    /** ISO 3166-1 alpha-2 derived from `DST_Ds`; `null` where it names no single coded territory. */
    readonly countryIso: string | null;
    /** Derived from the `DST_Ds` suffix; `null` only if the suffix is absent. */
    readonly entityType: CountryTaxIdEntityType | null;
}

